  <?php include __DIR__ . '/includes/footer.php'; ?>
  <div class="toast" id="toast">Link copiat.</div>

  <script>
  (()=>{
    'use strict';
    const $=(s,p=document)=>p.querySelector(s), $$=(s,p=document)=>Array.from(p.querySelectorAll(s));
    const body=document.body, nav=$('#siteNav'), progress=$('#scrollProgress'), menu=$('#mobileMenu'), tocSheet=$('#tocSheet');
    const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
    function setMenu(open){menu?.classList.toggle('open',open);menu?.setAttribute('aria-hidden',String(!open));body.style.overflow=open?'hidden':''}
    function setToc(open){tocSheet.classList.toggle('open',open);tocSheet.setAttribute('aria-hidden',String(!open));body.style.overflow=open?'hidden':''}
    $('#menuOpen')?.addEventListener('click',()=>setMenu(true));$('#menuClose')?.addEventListener('click',()=>setMenu(false));$('#menuBackdrop')?.addEventListener('click',()=>setMenu(false));$('#tocOpen').addEventListener('click',()=>setToc(true));$('#tocClose').addEventListener('click',()=>setToc(false));$('#tocBackdrop').addEventListener('click',()=>setToc(false));
    function onScroll(){const y=scrollY,max=document.documentElement.scrollHeight-innerHeight;nav?.classList.toggle('scrolled',y>20);progress.style.transform=`scaleX(${max>0?Math.min(1,y/max):0})`}addEventListener('scroll',onScroll,{passive:true});onScroll();
    if(!reduce&&'IntersectionObserver'in window){const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.animate([{opacity:0,transform:'translateY(26px)'},{opacity:1,transform:'none'}],{duration:620,easing:'cubic-bezier(.2,.75,.2,1)',fill:'forwards'});io.unobserve(e.target)}}),{threshold:.1});$$('[data-reveal],.legal-section').forEach(el=>io.observe(el))}else{$$('[data-reveal],.legal-section').forEach(el=>{el.style.opacity=1;el.style.transform='none'})}
    const sections=$$('.legal-section');
    const links=sections.map((section,i)=>({id:section.id,no:String(i+1).padStart(2,'0'),title:section.dataset.title}));
    function tocHtml(){return links.map(l=>`<a href="#${l.id}" data-toc="${l.id}"><span>${l.no}</span><span>${l.title}</span></a>`).join('')}
    $('#desktopToc').innerHTML=tocHtml();$('#mobileToc').innerHTML=tocHtml();
    $$('[data-toc]').forEach(a=>a.addEventListener('click',()=>setToc(false)));
    if('IntersectionObserver'in window){const spy=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!visible)return;$$('[data-toc]').forEach(a=>a.classList.toggle('active',a.dataset.toc===visible.target.id))},{rootMargin:'-25% 0px -58% 0px',threshold:[.05,.2,.4]});sections.forEach(s=>spy.observe(s))}
    function animatePath(path,marker){if(!path||!marker||reduce)return;const len=path.getTotalLength();path.style.strokeDasharray=len;path.style.strokeDashoffset=len;path.animate([{strokeDashoffset:len},{strokeDashoffset:0}],{duration:1900,delay:260,easing:'cubic-bezier(.2,.75,.2,1)',fill:'forwards'});const start=performance.now()+260;function frame(t){const p=Math.max(0,Math.min(1,(t-start)/1900)),pt=path.getPointAtLength(len*p);marker.setAttribute('cx',pt.x);marker.setAttribute('cy',pt.y);if(p<1)requestAnimationFrame(frame)}requestAnimationFrame(frame)}animatePath($('#heroRoute'),$('#heroMarker'));
    const search=$('#legalSearch'), noResults=$('#noResults');
    function normalize(v){return v.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim()}
    function clearMarks(root){$$('mark',root).forEach(m=>m.replaceWith(document.createTextNode(m.textContent)));root.normalize()}
    function highlight(root,q){if(!q||q.length<3)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement&&['SCRIPT','STYLE','MARK'].includes(n.parentElement.tagName)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.slice(0,40).forEach(node=>{const text=node.nodeValue,idx=normalize(text).indexOf(q);if(idx<0)return;const range=document.createRange();range.setStart(node,idx);range.setEnd(node,Math.min(text.length,idx+q.length));const mark=document.createElement('mark');try{range.surroundContents(mark)}catch(e){}})}
    function filter(){const q=normalize(search.value);let count=0;sections.forEach(section=>{clearMarks(section);const hay=normalize(section.dataset.title+' '+section.dataset.search+' '+section.textContent);const show=!q||hay.includes(q);section.hidden=!show;if(show){count++;highlight(section,q)}});noResults.classList.toggle('show',count===0)}
    search.addEventListener('input',filter);
    const toast=$('#toast');function showToast(text){toast.textContent=text;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2100)}
    $('#printButton').addEventListener('click',()=>window.print());
    $('#copyButton').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);showToast('Linkul documentului a fost copiat.')}catch(e){showToast('Copiază linkul din bara browserului.')}});
    addEventListener('keydown',e=>{if(e.key==='Escape'){setMenu(false);setToc(false)}});
  })();
  </script>
</body>
</html>
